function navLink(page,label,icon){return `<a class="nav-link ${route()===page?'active':''}" href="#${page}"><span>${ICON[icon]||'•'}</span>${label}${page==='notifications'&&notifCount?`<b class="nav-count">${notifCount}</b>`:''}</a>`;}
