function selectField(label,name,value,options){return `<label class="field"><span>${label}</span><select class="select" name="${name}">${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function textareaField(label,name,value='',placeholder=''){return `<label class="field full"><span>${label}</span><textarea class="textarea" name="${name}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;}
function btn(label,action,kind='btn',attrs=''){return `<button class="${kind}" data-action="${action}" ${attrs}>${label}</button>`;}
function empty(title,desc,actionLabel='',action=''){return `<div class="empty-state"><div class="empty-icon">✧</div><strong>${title}</strong><p>${desc}</p>${actionLabel?btn(actionLabel,action,'btn btn-primary btn-sm'):''}</div>`;}
