function profileCompletion(p){const keys=['displayName','dateOfBirth','gender','phone','emergencyContactName','emergencyContactPhone','bloodGroup','city','country','profileVisibility'];return Math.round(keys.filter(k=>p?.[k]).length/keys.length*100);}
